function evidence = simuverity_run_candidate_evidence( ...
        candidatePath, outDir, spec)
%SIMUVERITY_RUN_CANDIDATE_EVIDENCE Score-free candidate simulation kernel.
%
% The caller owns all task semantics: scenarios, input construction,
% required public Timeseries, scenario-specific derivation, and structural
% qualification.  This shared layer only enforces the P9/D16-style runtime
% boundary: a sealed candidate is copied to a fresh evaluation directory,
% loaded without saving, run once per scenario in one MATLAB
% session, and emitted as complete raw waveforms plus compact JSON evidence.
arguments
    candidatePath (1,1) string
    outDir (1,1) string
    spec (1,1) struct
end

localValidateSpec(spec);
candidatePath = localCanonical(candidatePath);
outDir = localCanonical(outDir);
assert(isfile(candidatePath), "SimuVerity:Formal90:Candidate:Missing", ...
    "Candidate model is missing: %s", candidatePath);
assert(~isfile(outDir) && ~isfolder(outDir), ...
    "SimuVerity:Formal90:Candidate:OutputReuse", ...
    "Candidate evidence output already exists: %s", outDir);

generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
assert(strlength(generationRunId) > 0, "SimuVerity:Formal90:Candidate:GenerationRunId", ...
    "SIMUVERITY_GENERATION_RUN_ID is required.");
localConfigureFileGeneration;
mkdir(outDir);
runtimeDir = fullfile(outDir, "candidate_runtime");
mkdir(runtimeDir);
[~, modelName, extension] = fileparts(candidatePath);
assert(any(lower(string(extension)) == [".slx", ".mdl"]), ...
    "SimuVerity:Formal90:Candidate:ModelType", ...
    "Candidate must be a Simulink SLX or MDL model.");
runtimeModelPath = fullfile(runtimeDir, modelName + extension);
assert(copyfile(candidatePath, runtimeModelPath, "f"), ...
    "SimuVerity:Formal90:Candidate:Copy", ...
    "Could not copy the sealed candidate into its evaluation directory.");

pathBefore = path;
pathCleanup = onCleanup(@() path(pathBefore)); %#ok<NASGU>
addpath(runtimeDir, "-begin");
evidence = localEmptyEvidence(spec, generationRunId, candidatePath);
fatal = [];
model = string(modelName);

try
    % The dispatcher may already have loaded the sealed runtime-bundle copy.
    % Close only that same model name, without saving, before loading this
    % evaluator-owned runtime copy; unrelated loaded models remain untouched.
    if bdIsLoaded(model), close_system(model, 0); end
    load_system(runtimeModelPath);
    evidence.load_pass = true;
    set_param(model, "ReturnWorkspaceOutputs", "on", ...
        "SignalLogging", "on", "SignalLoggingName", "logsout", ...
        "LimitDataPoints", "off");
    evidence.static_audit = spec.static_audit(model, spec);
    evidence.profile = localProfile(model, spec.output_contract);

    % A candidate is allowed to reference the declared public inputs from
    % the base workspace.  Seed the first fixed scenario before the initial
    % update/compile; otherwise a valid self-contained model can fail only
    % because the evaluator has not installed its inputs yet.
    initialScenario = localScenarioAt(spec.scenarios, 1);
    initialInputs = spec.input_builder(initialScenario, spec);
    assert(isstruct(initialInputs) && isscalar(initialInputs), ...
        "SimuVerity:Formal90:Candidate:Inputs", ...
        "Task input_builder must return one scalar struct.");
    localAssignBaseInputs(initialInputs);

    try
        set_param(model, "SimulationCommand", "update");
        evidence.update_pass = true;
    catch ME
        evidence.errors.update = localError(ME);
    end
    if evidence.update_pass
        compiled = false;
        try
            feval(model, [], [], [], "compile");
            compiled = true;
            evidence.compile_pass = true;
        catch ME
            evidence.errors.compile = localError(ME);
        end
        if compiled
            try, feval(model, [], [], [], "term"); catch, end
        end
    end

    rows = repmat(localEmptyScenario, numel(spec.scenarios), 1);
    if evidence.update_pass && evidence.compile_pass
        for index = 1:numel(spec.scenarios)
            scenario = localScenarioAt(spec.scenarios, index);
            row = localEmptyScenario;
            row.id = string(scenario.id);
            if isfield(scenario, "class")
                row.class = string(scenario.class);
            end
            row.started_at = localNow;
            timer = tic;
            try
                inputs = spec.input_builder(scenario, spec);
                assert(isstruct(inputs) && isscalar(inputs), ...
                    "SimuVerity:Formal90:Candidate:Inputs", ...
                    "Task input_builder must return one scalar struct.");
                if isfield(spec, "requested_input_builder")
                    row.requested_inputs = ...
                        spec.requested_input_builder(scenario, spec);
                else
                    row.requested_inputs = inputs;
                end
                stopTime = double(spec.stop_time(scenario, spec));
                assert(isscalar(stopTime) && isfinite(stopTime) && ...
                    stopTime > 0, "SimuVerity:Formal90:Candidate:StopTime", ...
                    "Scenario stop time must be one positive finite scalar.");
                row.stop_time_s = stopTime;
                localClearPublicOutputs(spec.output_contract);
                simInput = Simulink.SimulationInput(model);
                inputNames = string(fieldnames(inputs));
                for inputName = inputNames'
                    simInput = simInput.setVariable( ...
                        char(inputName), inputs.(inputName));
                end
                simInput = simInput.setModelParameter( ...
                    "StartTime", "0", ...
                    "StopTime", num2str(stopTime, 17), ...
                    "ReturnWorkspaceOutputs", "on", ...
                    "SignalLogging", "on", ...
                    "SignalLoggingName", "logsout", ...
                    "LimitDataPoints", "off");
                simOut = sim(simInput);
                [outputs, rawSignals, contract] = ...
                    localCollectOutputs(simOut, spec.output_contract, ...
                    stopTime, double(spec.evidence_sample_s), spec);
                scenarioDir = fullfile(outDir, ...
                    "scenario_" + localSafeId(row.id));
                mkdir(scenarioDir);
                waveformPath = fullfile(scenarioDir, "waveforms.mat");
                save(waveformPath, "rawSignals", "-v7.3");
                row.waveform_path = "scenario_" + ...
                    localSafeId(row.id) + "/waveforms.mat";
                row.output_contract = contract;
                row.scenario_application_pass = true;
                row.simulation_pass = true;
                row.required_evidence_pass = contract.all_required_pass;
                row.outputs = outputs;
                row = spec.postprocess(row, outputs, scenario, spec);
                row.valid = logical(row.simulation_pass && ...
                    row.scenario_application_pass && ...
                    row.required_evidence_pass && row.valid);
                row.success = row.valid;
            catch ME
                if string(ME.identifier) == ...
                        "SimuVerity:UnifiedOutput:EvaluatorContract"
                    rethrow(ME)
                end
                row.error = localError(ME);
            end
            row.wall_clock_seconds = toc(timer);
            row.finished_at = localNow;
            rows(index) = row;
            clear simOut rawSignals outputs
        end
    end
    evidence.scenarios = rows;
catch ME
    fatal = ME;
    evidence.errors.session = localError(ME);
end

try
    if bdIsLoaded(model), close_system(model, 0); end
    evidence.model_closed_without_save = true;
catch ME
    evidence.errors.close_model = localError(ME);
end
validRows = false(numel(evidence.scenarios), 1);
if ~isempty(evidence.scenarios)
    validRows = logical([evidence.scenarios.valid]);
end
evidence.nominal_smoke_pass = ~isempty(validRows) && validRows(1);
evidence.platform_valid = evidence.load_pass && evidence.update_pass && ...
    evidence.compile_pass && evidence.model_closed_without_save;
evidence.score_inputs_valid = evidence.platform_valid && ...
    numel(evidence.scenarios) == numel(spec.scenarios) && all(validRows);
evidence.diagnostics_valid = evidence.score_inputs_valid;
evidence.evidence_complete = evidence.score_inputs_valid;
evidence.finished_at = localNow;
if isfield(spec, "finalize_evidence")
    assert(isa(spec.finalize_evidence, "function_handle"), ...
        "SimuVerity:Formal90:Candidate:Spec", ...
        "Optional finalize_evidence hook must be a function handle.");
    evidence = spec.finalize_evidence(evidence, spec);
    assert(isstruct(evidence) && isscalar(evidence), ...
        "SimuVerity:Formal90:Candidate:Spec", ...
        "Optional finalize_evidence hook must return one scalar struct.");
end
evidencePath = fullfile(outDir, "evidence.json");
localWriteJsonExclusive(evidencePath, evidence);
evidence.evidence_path = localCanonical(evidencePath);

if ~isempty(fatal), rethrow(fatal); end
assert(evidence.score_inputs_valid, ...
    "SimuVerity:Formal90:Candidate:EvidenceIncomplete", ...
    "%s candidate evidence did not complete every required stage.", ...
    string(spec.task_id));
end

function scenario = localScenarioAt(scenarios, index)
if iscell(scenarios)
    scenario = scenarios{index};
else
    scenario = scenarios(index);
end
end

function localAssignBaseInputs(inputs)
names = string(fieldnames(inputs));
for name = names'
    assignin("base", char(name), inputs.(name));
end
end

function localValidateSpec(spec)
required = ["schema", "task_id", "scenarios", "output_contract", ...
    "input_builder", "stop_time", "postprocess", "static_audit", ...
    "evidence_sample_s"];
for name = required
    assert(isfield(spec, name), "SimuVerity:Formal90:Candidate:Spec", ...
        "Candidate adapter spec is missing %s.", name);
end
assert(~isempty(spec.scenarios), "SimuVerity:Formal90:Candidate:Spec", ...
    "Candidate adapter requires at least one official scenario.");
assert(isstruct(spec.output_contract) && ...
    all(isfield(spec.output_contract, ...
    {'name', 'evidence_name', 'width', 'interpolation'})), ...
    "SimuVerity:Formal90:Candidate:Spec", ...
    "Output contract rows require name/evidence_name/width/interpolation.");
assert(isa(spec.input_builder, "function_handle") && ...
    isa(spec.stop_time, "function_handle") && ...
    isa(spec.postprocess, "function_handle") && ...
    isa(spec.static_audit, "function_handle"), ...
    "SimuVerity:Formal90:Candidate:Spec", ...
    "Task hooks must be function handles.");
assert(isscalar(spec.evidence_sample_s) && ...
    isfinite(spec.evidence_sample_s) && spec.evidence_sample_s > 0, ...
    "SimuVerity:Formal90:Candidate:Spec", ...
    "evidence_sample_s must be positive and finite.");
names = string({spec.output_contract.name});
evidenceNames = string({spec.output_contract.evidence_name});
assert(numel(unique(names)) == numel(names) && ...
    numel(unique(evidenceNames)) == numel(evidenceNames), ...
    "SimuVerity:Formal90:Candidate:Spec", ...
    "Output names and evidence names must be unique.");
end

function evidence = localEmptyEvidence(spec, generationRunId, candidatePath)
[~, candidateName, candidateExtension] = fileparts(candidatePath);
candidateArtifact = candidateName + candidateExtension;
evidence = struct( ...
    "schema", string(spec.schema), ...
    "task_id", string(spec.task_id), ...
    "generation_run_id", generationRunId, ...
    "candidate_path", "sealed_candidate/" + candidateArtifact, ...
    "runtime_model_path", "candidate_runtime/" + candidateArtifact, ...
    "adapter", "simuverity-public-output-compatibility", ...
    "reference_identity_applicable", false, ...
    "reference_substantive_modifications", 0, ...
    "sealed_candidate_substantive_modifications", 0, ...
    "evaluation_model_substantive_modifications", 0, ...
    "extraction_only", true, ...
    "contains_score_decisions", false, ...
    "load_pass", false, ...
    "update_pass", false, ...
    "compile_pass", false, ...
    "nominal_smoke_pass", false, ...
    "model_closed_without_save", false, ...
    "platform_valid", false, ...
    "score_inputs_valid", false, ...
    "diagnostics_valid", false, ...
    "evidence_complete", false, ...
    "static_audit", struct, ...
    "profile", struct, ...
    "scenarios", struct([]), ...
    "errors", struct, ...
    "runtime", localRuntime(generationRunId), ...
    "started_at", localNow, ...
    "finished_at", "");
end

function row = localEmptyScenario
row = struct( ...
    "id", "", ...
    "class", "", ...
    "requested_inputs", struct, ...
    "stop_time_s", 0.0, ...
    "scenario_application_pass", false, ...
    "simulation_pass", false, ...
    "required_evidence_pass", false, ...
    "valid", false, ...
    "success", false, ...
    "simulate_pass", false, ...
    "output_contract", struct, ...
    "outputs", struct, ...
    "logs", struct, ...
    "input", struct, ...
    "metrics", struct, ...
    "offline_metrics", struct, ...
    "applied_parameters", struct, ...
    "map_occupied_fraction", 0.0, ...
    "waveform_path", "", ...
    "lap_completion_s", 0.0, ...
    "error", struct, ...
    "wall_clock_seconds", 0.0, ...
    "started_at", "", ...
    "finished_at", "");
end

function [outputs, rawSignals, contract] = localCollectOutputs( ...
        simOut, definitions, stopTime, sampleStep, spec)
rawSignals = struct;
series = repmat(struct("time", [], "data", []), numel(definitions), 1);
contract = struct;
contractFields = strings(numel(definitions), 1);
basePass = false(numel(definitions), 1);
for index = 1:numel(definitions)
    definition = definitions(index);
    allowedWidths = double(definition.width(:));
    [value, adapter] = simuverity_public_output_compatibility( ...
        simOut, string(definition.name), allowedWidths, ...
        AllowBaseWorkspace=true);
    time = double(value.Time(:));
    data = double(value.Data);
    if size(data, 1) ~= numel(time)
        data = reshape(data, numel(time), []);
    else
        data = reshape(data, numel(time), []);
    end
    widthPass = any(size(data, 2) == allowedWidths);
    basePass(index) = numel(time) >= 2 && widthPass && ...
        all(isfinite(time)) && all(isfinite(data), "all") && ...
        all(diff(time) > 0) && ...
        time(1) <= max(1e-8, sampleStep);
    rawSignals.(char(definition.evidence_name)) = value;
    series(index).time = time;
    series(index).data = data;
    field = matlab.lang.makeValidName( ...
        string(definition.evidence_name) + "_pass");
    adapterField = matlab.lang.makeValidName( ...
        string(definition.evidence_name) + "_adapter");
    contract.(adapterField) = adapter;
    contractFields(index) = field;
end

coverageMode = "stop_time";
if isfield(spec, "coverage_mode")
    coverageMode = string(spec.coverage_mode);
end
switch coverageMode
    case "stop_time"
        coveragePass = arrayfun(@(row) ...
            row.time(end) >= stopTime - max(1e-8, sampleStep), series);
        outputEnd = stopTime;
        if isfield(spec, "evidence_sample_count")
            sampleCount = max(2, ...
                round(double(spec.evidence_sample_count)));
            timeGrid = linspace(0, stopTime, sampleCount)';
        else
            timeGrid = localTimeGrid(stopTime, sampleStep);
        end
    case "event_terminated"
        endTimes = arrayfun(@(row) row.time(end), series);
        outputEnd = min(endTimes);
        endpointTolerance = max(1e-8, 1e-6 * max(outputEnd, 1));
        coveragePass = endTimes >= max(endTimes) - endpointTolerance;
        sampleCount = max(2, floor(outputEnd / sampleStep) + 1);
        if isfield(spec, "evidence_sample_count")
            sampleCount = max(2, round(double(spec.evidence_sample_count)));
        end
        timeGrid = linspace(0, outputEnd, sampleCount)';
    otherwise
        error("SimuVerity:Formal90:Candidate:CoverageMode", ...
            "Unsupported evidence coverage mode: %s", coverageMode);
end
for index = 1:numel(definitions)
    pass = basePass(index) && coveragePass(index);
    assert(pass, "SimuVerity:Formal90:Candidate:OutputContract", ...
        "Required public output %s violates allowed width, finiteness, monotonicity, or run-coverage requirements.", ...
        string(definitions(index).name));
    contract.(contractFields(index)) = logical(pass);
end

% Preserve explicitly declared discrete event transitions even when the
% compact evidence grid is much coarser than the raw simulation signal.
eventTimes = zeros(0, 1);
for index = 1:numel(definitions)
    definition = definitions(index);
    if ~isfield(definition, "event_columns") || ...
            isempty(definition.event_columns)
        continue
    end
    columns = double(definition.event_columns(:)');
    assert(all(columns >= 1) && ...
        all(columns <= size(series(index).data, 2)), ...
        "SimuVerity:Formal90:Candidate:EventColumns", ...
        "Event columns are outside required output %s.", ...
        string(definition.name));
    eventData = series(index).data(:, columns);
    changed = [true; any(diff(eventData, 1, 1) ~= 0, 2)];
    eventTimes = [eventTimes; series(index).time(changed)]; %#ok<AGROW>
end
if ~isempty(eventTimes)
    eventTimes = eventTimes(eventTimes >= 0 & eventTimes <= outputEnd);
    timeGrid = unique([timeGrid; eventTimes], "sorted");
end
outputs = struct("time_s", timeGrid);
for index = 1:numel(definitions)
    definition = definitions(index);
    method = char(definition.interpolation);
    data = interp1(series(index).time, series(index).data, ...
        timeGrid, method, "extrap");
    outputs.(char(definition.evidence_name)) = double(data);
end
contract.all_required_pass = all(arrayfun(@(index) ...
    logical(contract.(contractFields(index))), ...
    1:numel(contractFields)));
contract.sample_count = numel(timeGrid);
contract.time_start_s = timeGrid(1);
contract.time_end_s = timeGrid(end);
contract.coverage_mode = coverageMode;
end

function localClearPublicOutputs(definitions)
for name = string({definitions.name})
    escaped = replace(name, "'", "''");
    evalin("base", "if exist('" + escaped + "','var'), clear('" + ...
        escaped + "'); end");
end
end

function time = localTimeGrid(stopTime, step)
count = max(2, floor(stopTime / step) + 1);
time = (0:count-1)' * step;
if time(end) < stopTime
    time(end+1, 1) = stopTime;
elseif time(end) > stopTime
    time(end) = stopTime;
end
time = unique(time, "stable");
end

function profile = localProfile(model, definitions)
blocks = find_system(model, "LookUnderMasks", "all", ...
    "FollowLinks", "on", "Type", "Block");
profile = struct( ...
    "block_count", numel(blocks), ...
    "required_public_output_count", numel(definitions), ...
    "required_public_output_names", string({definitions.name}), ...
    "candidate_only", true);
end

function localConfigureFileGeneration
cacheDir = string(getenv("SIMULINK_CACHE_FOLDER"));
codegenDir = string(getenv("SIMULINK_CODEGEN_FOLDER"));
assert(strlength(cacheDir) > 0 && strlength(codegenDir) > 0, ...
    "SimuVerity:Formal90:Candidate:Isolation", ...
    "Isolated Simulink cache and codegen folders are required.");
if ~isfolder(cacheDir), mkdir(cacheDir); end
if ~isfolder(codegenDir), mkdir(codegenDir); end
Simulink.fileGenControl("set", "CacheFolder", cacheDir, ...
    "CodeGenFolder", codegenDir, "createDir", true);
set(groot, "defaultFigureVisible", "off");
end

function runtime = localRuntime(generationRunId)
runtime = struct( ...
    "generation_run_id", generationRunId, ...
    "matlab_release", string(version("-release")), ...
    "matlab_prefdir_configured", strlength(string(prefdir)) > 0, ...
    "appdata_configured", strlength(string(getenv("APPDATA"))) > 0, ...
    "localappdata_configured", ...
        strlength(string(getenv("LOCALAPPDATA"))) > 0, ...
    "temp_configured", strlength(string(getenv("TEMP"))) > 0, ...
    "cache_configured", ...
        strlength(string(getenv("SIMULINK_CACHE_FOLDER"))) > 0, ...
    "codegen_configured", ...
        strlength(string(getenv("SIMULINK_CODEGEN_FOLDER"))) > 0, ...
    "mcp_port_assigned", ...
        strlength(string(getenv("SIMUVERITY_MCP_PORT"))) > 0, ...
    "matlab_start_count", 1);
end

function value = localSafeId(value)
value = regexprep(string(value), "[^A-Za-z0-9._-]", "_");
assert(strlength(value) > 0, "SimuVerity:Formal90:Candidate:ScenarioId", ...
    "Scenario id is empty after normalization.");
end

function payload = localError(ME)
payload = struct( ...
    "identifier", string(ME.identifier), ...
    "message", localSanitizeText(string(ME.message)));
end

function value = localSanitizeText(value)
isolatedValues = [string(prefdir), string(getenv("APPDATA")), ...
    string(getenv("LOCALAPPDATA")), string(getenv("TEMP")), ...
    string(getenv("TMP")), string(getenv("SIMULINK_CACHE_FOLDER")), ...
    string(getenv("SIMULINK_CODEGEN_FOLDER"))];
for isolatedValue = isolatedValues
    if strlength(isolatedValue) > 0
        value = replace(value, isolatedValue, "<isolated-path>");
    end
end
value = regexprep(value, ...
    "(?i)(api[_-]?key|token|secret)\s*[=:]\s*[^\s,;]+", ...
    "$1=<redacted>");
value = regexprep(value, ...
    "(?<![A-Za-z0-9_])[A-Za-z]:[\\/][^\s,;""']+", "<path>");
value = regexprep(value, "\\\\[^\s,;""']+", "<path>");
end

function value = localCanonical(pathIn)
value = string(java.io.File(char(pathIn)).getCanonicalPath());
end

function localWriteJsonExclusive(pathOut, payload)
assert(~isfile(pathOut) && ~isfolder(pathOut), ...
    "SimuVerity:Formal90:Candidate:EvidenceOverwrite", ...
    "Refusing to overwrite candidate evidence: %s", pathOut);
temporary = pathOut + ".staging-" + string(java.util.UUID.randomUUID);
created = java.io.File(char(temporary)).createNewFile();
assert(created, "SimuVerity:Formal90:Candidate:EvidenceCreate", ...
    "Cannot create staged candidate evidence exclusively.");
fid = fopen(temporary, "w", "n", "UTF-8");
assert(fid >= 0, "SimuVerity:Formal90:Candidate:EvidenceCreate", ...
    "Cannot create staged candidate evidence.");
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(payload, PrettyPrint=true), "char");
clear cleanup
assert(~isfile(pathOut) && movefile(temporary, pathOut), ...
    "SimuVerity:Formal90:Candidate:EvidencePublish", ...
    "Could not atomically publish candidate evidence.");
end

function value = localNow
value = string(datetime("now", "TimeZone", "UTC", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"));
end
